          if (selected.startsWith("repcfg_removerole_")) {
            guildData(gId).reports.pingRole = null;
            saveDB();
            return interaction.reply({ components: [createSuccessContainer("Ping Role Removed", "No role will be pinged for new reports.")], flags: MessageFlags.IsComponentsV2 | 64 });
          }
          if (selected.startsWith("repcfg_anon_")) {
            const current = guildData(gId).reports.anonymous;
            guildData(gId).reports.anonymous = !current;
            saveDB();
            return interaction.reply({
              components: [createSuccessContainer(
                !current ? "Anonymous Mode On" : "Anonymous Mode Off",
                !current ? "Reporter identities are now **hidden** from the report channel." : "Reporter identities are now **visible** in the report channel."
              )], flags: MessageFlags.IsComponentsV2 | 64
            });
          }
          if (selected.startsWith("repcfg_enable_")) {
            if (await replyInteractionSetupRequiredIfMissing(interaction, gId, "reports")) return;
            if (typeof setFeatureState === "function") setFeatureState(gId, "reports", true, { client: interaction.client });
            else { guildData(gId).reports.enabled = true; saveDB(); }
            return interaction.reply({ components: [createSuccessContainer("Reports Enabled", "The report system has been enabled!")], flags: MessageFlags.IsComponentsV2 | 64 });
          }
          if (selected.startsWith("repcfg_disable_")) {
            if (typeof setFeatureState === "function") setFeatureState(gId, "reports", false, { client: interaction.client });
            else { guildData(gId).reports.enabled = false; saveDB(); }
            return interaction.reply({ components: [createSuccessContainer("Reports Disabled", "The report system has been disabled!")], flags: MessageFlags.IsComponentsV2 | 64 });
          }
          if (selected.startsWith("repcfg_reset_")) {
            guildData(gId).reports.count = 0;
            saveDB();
            return interaction.reply({ components: [createSuccessContainer("Counter Reset", "The report counter has been reset to 0!")], flags: MessageFlags.IsComponentsV2 | 64 });
          }
