              new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId("inp_jd_message").setLabel("DM message ({user}, {server}, {membercount})").setStyle(TextInputStyle.Paragraph).setValue(guildData(guildId).joinDm?.message || "").setRequired(true).setMaxLength(1000))
