            modal.addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId("inp_gw_blacklist").setLabel("Role ID (optional; blank = none)").setStyle(TextInputStyle.Short).setPlaceholder("Leave blank for no blacklist").setValue(guildData(gId).giveawayConfig?.blacklistRole || "").setRequired(false).setMaxLength(20)));
            return interaction.showModal(modal);
