            modal.addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId("inp_eco_daily").setLabel("Daily claim amount").setStyle(TextInputStyle.Short).setValue(String(guildData(guildId).economy?.daily ?? 1)).setRequired(true).setMaxLength(7)));
            return interaction.showModal(modal);
