            modal.addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId("inp_cf_channel").setLabel("Channel ID for confessions").setStyle(TextInputStyle.Short).setPlaceholder("e.g. 123456789012345678").setValue(guildData(guildId).confession?.channel || "").setRequired(true).setMaxLength(20)));
